168	 * A `path` the caller sent as the JSON text of an array, turned back into an array.
169	 *
170	 * `path` takes one place or several, and the schema emits an `anyOf` — a string or an
171	 * array. Weaker models read that and, reaching for "several", send the array
172	 * *serialised*: `'["src/shared","src/adapters"]'`. The `string` arm accepts that, so
173	 * the whole text arrives at `grep` as one path and the failure it gets back names a
174	 * file that does not exist, which reads as a bad path rather than an unsupported
175	 * argument. The array form itself is fine — this repairs the one shape the `anyOf`
176	 * invites and a string arm then swallows. Same tolerance, and same reason, as
177	 * `stringArray`/`positiveInt` in `adapters/mcp/mcp-tool.ts`.
178	 *
179	 * Only a string that *is* a JSON array of strings is converted; every other string,
180	 * including one that merely looks like a path, is left alone.
181	 */
182	function serialisedPathList(value: unknown): unknown {
183	  if (typeof value !== "string") return value;
184	  const text = value.trim();
185	  if (!text.startsWith("[") || !text.endsWith("]")) return value;
186	  try {
187	    const parsed: unknown = JSON.parse(text);
188	    return Array.isArray(parsed) && parsed.every((one) => typeof one === "string") ? parsed : value;
189	  } catch {
190	    return value;
191	  }
192	}
