194	const GREP_SCHEMA = z.object({
195	  pattern: z.string().describe("Extended regular expression, as `grep -E` reads it."),
196	  path: z
197	    .preprocess(serialisedPathList, z.union([z.string(), z.array(z.string()).min(1)]))
198	    .optional()
199	    .describe("File or directory to search, or several of them. Default: the working directory."),
200	  glob: z
201	    .string()
202	    .optional()
203	    .describe("Only search files whose name matches this shell glob, such as `*.ts`. Matched against the file name, not the whole path."),
204	  exclude: z
205	    .array(z.string())
206	    .optional()
207	    .describe("Skip files and directories whose name matches any of these globs, such as `node_modules` or `*.min.js`."),
208	  context: z
209	    .number()
210	    .int()
211	    .min(0)
212	    .max(20)
213	    .optional()
214	    .describe("Lines of surrounding context to include with each match. Default 0."),
215	  max_matches: z
216	    .number()
217	    .int()
218	    .min(1)
219	    .optional()
220	    .describe(`How many lines to return. Default ${DEFAULT_MAX_MATCHES}. With context set, the surrounding lines count towards it. The result says when it stopped early.`),
221	  case_sensitive: z.boolean().optional().default(true).describe("Match case. Default true."),
222	});
