224	/**
225	 * Content search, with the file and line on every match.
226	 *
227	 * `grep -E` rather than ripgrep: ripgrep is not on the runner image, and installing it
228	 * on every run to gain speed on a repository this size would be paying for something
229	 * nobody has measured wanting.
230	 */
231	function grepFiles(a: z.infer<typeof GREP_SCHEMA>): McpToolResult {
232	  const asked = a.path === undefined ? ["."] : Array.isArray(a.path) ? a.path : [a.path];
233	  const limit = a.max_matches ?? DEFAULT_MAX_MATCHES;
234	
235	  // grep is given relative paths so that it prints relative paths, rather than being
236	  // given absolute ones and having the prefix cut off afterwards. Cutting at the first
237	  // colon is what a line like `C:\repo\file.ts:9:...` breaks, and the runner being
238	  // Linux is not a reason to write something that is wrong anywhere else.
239	  const targets = asked.map((one) => {
240	    const full = within(one);
241	    const rel = relative(process.cwd(), full);
242	    return rel === "" ? "." : rel.startsWith("..") ? full : rel.split(sep).join("/");
243	  });
244	
245	  const args = ["-E", "-n", "-I", "-r"];
246	  if (!a.case_sensitive) args.push("-i");
247	  if (a.context) args.push(`-C${a.context}`);
248	  if (a.glob) args.push(`--include=${a.glob}`);
249	  // Both forms per pattern, because a caller writing `node_modules` means the
250	  // directory and one writing `*.min.js` means the files, and asking which they meant
251	  // is a round trip to learn something neither of them cares about.
252	  for (const skip of a.exclude ?? []) {
253	    args.push(`--exclude=${skip}`, `--exclude-dir=${skip}`);
254	  }
255	  // `-m` is per file, not per search, so it does not bound the answer -- a hundred
256	  // files each stopping at the limit still returns a hundred times it. The bound that
257	  // holds is the slice below; this only stops one pathological file filling the buffer.
258	  args.push(`-m${limit + 1}`, "-e", a.pattern, "--", ...targets);
259	
260	  const run = spawnSync("grep", args, { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
261	  if (run.error) throw new Error(`grep could not be run: ${run.error.message}`);
262	  // grep exits 1 for "no matches", which is an answer rather than a failure. Anything
263	  // above that is the tool failing, and saying so matters: a broken search and a clean
264	  // repository return the same empty result otherwise.
265	  if (run.status !== null && run.status > 1) {
266	    throw new Error(`grep failed (exit ${run.status}): ${(run.stderr || "").trim() || "no output"}`);
267	  }
268	
269	  const found = (run.stdout || "").split("\n").filter((line) => line.length > 0);
270	  if (found.length === 0) {
271	    return {
272	      text: `No match for ${a.pattern}${a.glob ? ` in ${a.glob} files` : ""} under ${targets.join(", ")}.`,
273	    };
274	  }
275	
276	  const kept: string[] = [];
277	  let used = 0;
278	  for (const line of found.slice(0, limit)) {
279	    if (used + line.length + 1 > TOOL_OUTPUT_BUDGET) break;
280	    kept.push(line);
281	    used += line.length + 1;
282	  }
283	
284	  const dropped = found.length - kept.length;
285	  const note =
286	    dropped > 0
287	      ? `\n\n[${dropped} or more further lines. Narrow the pattern, set glob, or raise max_matches.]`
288	      : "";
289	  // Lines, not matches: with context set, most of them are the lines around one.
290	  const what = a.context ? "line(s), match and context," : "matching line(s)";
291	  log(`grep ${a.pattern} -> ${kept.length} line(s)${dropped > 0 ? `, ${dropped} dropped` : ""}`);
292	  return { text: `${kept.length} ${what} under ${targets.join(", ")}:\n\n${kept.join("\n")}${note}` };
293	}
294	
295	const GLOB_SCHEMA = z.object({
296	  pattern: z.string().describe("Glob over paths, such as `src/**/*.ts`. Matched against the path relative to `path`."),
297	  path: z.string().optional().describe("Directory to search under. Default: the working directory."),
298	});
