300	/** File names matching a glob, most recently changed first. */
301	function globFiles(a: z.infer<typeof GLOB_SCHEMA>): McpToolResult {
302	  const root = within(a.path ?? ".");
303	  const found: { path: string; at: number }[] = [];
304	  for (const hit of new Bun.Glob(a.pattern).scanSync({ cwd: root, onlyFiles: true, dot: false })) {
305	    const full = resolve(root, hit);
306	    try {
307	      found.push({ path: shown(full), at: statSync(full).mtimeMs });
308	    } catch {
309	      // Gone between the scan and the stat. Not an error: it is simply not there.
310	    }
311	  }
312	  if (found.length === 0) return { text: `No file matches ${a.pattern} under ${shown(root)}.` };
313	
314	  // Most recently changed first: the file somebody is working on is the one being
315	  // looked for, and alphabetical order buries it among its neighbours.
316	  found.sort((x, y) => y.at - x.at);
317	  const kept: string[] = [];
318	  let used = 0;
319	  for (const { path } of found) {
320	    if (used + path.length + 1 > TOOL_OUTPUT_BUDGET) break;
321	    kept.push(path);
322	    used += path.length + 1;
323	  }
324	  const dropped = found.length - kept.length;
325	  const note = dropped > 0 ? `\n\n[${dropped} more. Narrow the pattern.]` : "";

